/// <summary>
/// AVA_7507_CalcDestinationWithAllPostingLayers
/// </summary>
/// <param name = "_basisId">LedgerAllocationBasisNum</param>
/// <param name = "_company">dataAreaId</param>
/// <returns>Query</returns>
protected final Query createGeneralJournalAccountEntrySumQuery(
    LedgerAllocationBasisNum _basisId,
    dataAreaId _company)
{
    LedgerAllocationRuleID                  ruleId;
    //AVALedgerAllocationRuleOperationsTax    oprTax;
    AVAFPLLedgerAllocationRuleOperationsTax oprTax;
    LedgerAllocationRuleDestination         ruleDestination;
    Query                                   query;
    QueryBuildDataSource                    qbdsHeader;

    query = next createGeneralJournalAccountEntrySumQuery(_basisId, _company);

    select firstonly RuleID from ruleDestination where ruleDestination.BasisId == _basisId
                                                    && ruleDestination.DataAreaId   == _company;
    ruleId = ruleDestination.RuleID;
    qbdsHeader = SysQuery::findOrCreateDataSource(query, tableNum(GeneralJournalEntry));
    qbdsHeader.clearRange(fieldNum(GeneralJournalEntry, PostingLayer));
    while select oprTax where oprTax.RuleId == ruleId
    {
        qbdsHeader.addRange(fieldNum(GeneralJournalEntry, PostingLayer)).value(queryValue(oprTax.CurrentOperationsTax));
    }

    return query;
}
